import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
import { mockTrips as mockTrips2, companies } from "npm:@/data/mockTrips";
var get_trip_details_default = defineTool2({
  name: "get_trip_details",
  title: "Get trip details",
  description: "Fetch the full details of a Trippinity trip by id: itinerary, dates, gallery, planner and company info.",
  inputSchema: {
    id: z2.string().min(1).describe("The trip id, e.g. '1'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const trip = mockTrips2.find((t) => t.id === id);
    if (!trip) {
      return {
        content: [{ type: "text", text: `No trip found with id "${id}".` }],
        isError: true
      };
    }
    const company = companies[trip.companyId] ?? null;
    const detail = { ...trip, company };
    return {
      content: [{ type: "text", text: JSON.stringify(detail, null, 2) }],
      structuredContent: detail
    };
  }
});

